<template><section class="chart-presentation-picker"><h3>展示方案</h3><div><button v-for="preset in presets" :key="preset.id" type="button" @click="$emit('select', preset.id)"><i :class="`is-${kind} is-${preset.id}`"><b/><b/><b/></i><span>{{ preset.label }}</span></button></div></section></template>
